export class SimulatorAdapter{constructor(device){this.device=device;this.connected=true;this.listeners=new Set;this.view=device.snapshot();this.failNext=false;this.pending=false}subscribe(fn){this.listeners.add(fn);fn(this.state());return()=>this.listeners.delete(fn)}state(){return{connected:this.connected,pending:this.pending,device:this.view}}publish(){if(this.connected)this.view=this.device.snapshot();for(const fn of this.listeners)fn(this.state())}tick(dt){this.device.tick(dt);this.publish()}connect(v){if(!v)this.view=cp(this.view);this.connected=v;this.publish()}async command(type,p={}){if(!this.connected)throw Error('Нет связи с прибором.');if(this.pending)throw Error('Дождитесь подтверждения предыдущей команды.');this.pending=true;this.publish();try{await new Promise(r=>setTimeout(r,220));if(!this.connected)throw Error('Связь потеряна. Команда не подтверждена.');if(this.failNext){this.failNext=false;throw Error('Прибор отклонил команду. Повторите попытку.')}this.device.command(type,p)}finally{this.pending=false;this.publish()}}}
